-- GATE A–Z: paid previous-year papers (₹20 per paper, included with the ₹49 paper).
-- Run once in Supabase → SQL Editor. Safe to re-run: it replaces the data.
-- The PDF links live only here; the site shows years and asks get_pyqs() for links after purchase.

create table if not exists public.pyq (
  paper text primary key,          -- paper slug, e.g. 'ee'
  years jsonb not null             -- [{year, sets:[{label, qp, key}]}]
);
alter table public.pyq enable row level security;
revoke all on public.pyq from anon, authenticated;

-- Links for one paper: only for buyers of the PYQs ('pyq-ee') or of the full paper ('ee'), and admins.
create or replace function public.get_pyqs(p_paper text) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  if auth.uid() is null then raise exception 'sign in required'; end if;
  if not public.is_admin() and not exists (
    select 1 from public.entitlements e
    where e.user_id = auth.uid() and e.paper in (p_paper, 'pyq-' || p_paper) and e.expires_at > now()
  ) then raise exception 'not purchased'; end if;
  return (select years from public.pyq where paper = p_paper);
end $$;
revoke execute on function public.get_pyqs(text) from public, anon;
grant execute on function public.get_pyqs(text) to authenticated;

on conflict (paper) do update set years = excluded.years;

-- check: should list 30 papers
select paper, jsonb_array_length(years) as years from public.pyq order by paper;
